import { describe, expect, it } from 'vitest';
import { isAdult } from './age.ts';
describe('pinned age boundary', () => {
  it('rejects below the age of majority', () => { expect(isAdult(17)).toBe(false); });
  it('accepts at the age of majority', () => { expect(isAdult(18)).toBe(true); });
});
